examples.template:
ViewThatFits(in: .horizontal) {
    HStack(spacing: MonarchTokens.Space.space2) {
        MonarchAiConfidenceMeter(value: {{meters.0.value}})
        MonarchAiConfidenceMeter(value: {{meters.1.value}})
        MonarchAiConfidenceMeter(value: {{meters.2.value}}, showsValue: {{meters.2.showValue}})
    }
    VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
        MonarchAiConfidenceMeter(value: {{meters.0.value}})
        MonarchAiConfidenceMeter(value: {{meters.1.value}})
        MonarchAiConfidenceMeter(value: {{meters.2.value}}, showsValue: {{meters.2.showValue}})
    }
}

